}

/* ---------- receipt ---------- */
#receipt .receipt-card,#summary .receipt-card{
  animation:receipt-in .5s cubic-bezier(.2,.9,.25,1) both;
}
@keyframes receipt-in{
  from{opacity:0;translate:0 26px;rotate:-2deg;}
  to{opacity:1;translate:0 0;rotate:-.4deg;}
}
.receipt-card{
  position:relative;
  width:412px;
  background:
    linear-gradient(140deg, rgba(255,255,255,.55), transparent 42%),
    linear-gradient(180deg, #f8f0dd, #efe2c5);
  color:var(--ink);
  padding:26px 30px 24px;
  border-radius:2px;
  rotate:-.4deg;
  box-shadow:0 34px 60px rgba(0,0,0,.55), 0 1px 0 #fff inset;
}
.receipt-card::after{
  content:"";
  position:absolute;left:0;right:0;bottom:-11px;height:12px;
  background:
    linear-gradient(135deg, #efe2c5 25%, transparent 25%) -6px 0/12px 12px repeat-x,
    linear-gradient(225deg, #efe2c5 25%, transparent 25%) -6px 0/12px 12px repeat-x;
}
.receipt-head{
  display:flex;justify-content:space-between;align-items:baseline;
  font-family:"Courier New",monospace;font-size:9px;letter-spacing:2px;color:#735c40;
}
.receipt-head span:first-child{font-weight:700;color:#2c231c;letter-spacing:2.4px;}
.dash{border-top:1px dashed rgba(80,58,35,.4);margin:12px 0;}
.receipt-rows{font-family:"Courier New",monospace;font-size:11.5px;color:#4d3b2c;display:flex;flex-direction:column;gap:6px;}
.receipt-rows.refs div{display:flex;justify-content:space-between;gap:14px;}
.receipt-rows.refs div span:first-child{color:#8b7357;font-size:9px;letter-spacing:1.3px;text-transform:uppercase;padding-top:2px;}
.receipt-rows.refs div span:last-child{text-align:right;}
.receipt-rows:not(.refs) div{display:flex;justify-content:space-between;font-size:12px;}
.receipt-rows .total{
  display:flex;justify-content:space-between;
  border-top:1px solid rgba(80,58,35,.25);
  margin-top:7px;padding-top:9px;
  font-size:17px;font-weight:700;letter-spacing:.4px;
}
.receipt-rows .total span:last-child{font-size:21px;}
.receipt-stars{
  text-align:center;
  font-size:23px;letter-spacing:7px;
  color:#d79a34;
  margin-top:14px;
  min-height:29px;
  text-shadow:0 1px 0 #fff8;
}
.receipt-stars .dim{color:#cbb894;text-shadow:none;}
.receipt-comment{
  font-family:Georgia,serif;font-style:italic;
  font-size:12.5px;line-height:1.45;text-align:center;
  color:#6b553b;
  margin:7px 12px 2px;
}
.stamp{
  position:absolute;
  top:64px;right:24px;
  rotate:11deg;
  border:2.5px solid rgba(161,62,46,.6);
  color:rgba(161,62,46,.68);
  font-family:"Courier New",monospace;
  font-weight:700;
  font-size:14px;letter-spacing:2px;
  padding:4px 10px;
  border-radius:3px;
  opacity:.85;
}
#nextBtn{display:block;margin:20px auto 0;position:relative;z-index:2;}
.receipt-tail{
  text-align:center;
  font-family:"Courier New",monospace;font-size:7.5px;letter-spacing:2.4px;
  color:#9c8462;margin-top:14px;
}
.summary-card{width:452px;}
.summary-kicker{
  font-family:"Courier New",monospace;font-size:8.5px;letter-spacing:3px;
  color:#a97a42;text-align:center;margin-top:12px;
}
.summary-card h2{
  font-family:Georgia,serif;font-size:33px;margin:7px 0 2px;text-align:center;
  letter-spacing:-.5px;
}
.summary-card > p{text-align:center;font-family:Georgia,serif;font-style:italic;font-size:12.5px;color:#6b553b;margin:4px 8px 16px;}
.sum-stars{text-align:center;font-size:26px;letter-spacing:8px;color:#d79a34;min-height:30px;}
.summary-card .receipt-rows{gap:8px;margin-top:2px;}

@media (max-width:900px){
  #stage{transform-origin:center;}
