```js
function buildTasks(order){
 const P = {
  protector: () => [
    mkRemove('protector', 'Peel off the old film', 'Drag the cracked film into the broken-parts bin.'),
    mkClean('Wipe the glass', 'Drag the cloth across the screen until it sparkles.'),
    mkInstall('protector', 'Apply a fresh protector', 'Drag the protector from the parts tray onto the screen.'),
    mkSmooth(),
    mkTest()
  ],
  screen: () => [mkHeat(), mkScrews('bottom','Remove the bottom screws','Hold the driver on each pentalobe screw until it lifts out.'), mkPry(), mkDisconnect('display'), mkRemove('screen',...), mkInstall('screen',...), mkClose(), mkTest()],
 ...
 }
 return P[order.repair]();
}
```

