function makeCracks(seed){
 const r=mulberry32(seed);
 const cx=.55+r()*.2, cy=.22+r()*.15;
 const lines=[];
 const count=9+Math.floor(r()*5);
 for(let i=0;i<count;i++){
  let a=r()*Math.PI*2;
  const pts=[{x:cx,y:cy}];
  const len=3+Math.floor(r()*5);
  let x=cx,y=cy;
  for(let j=0;j<len;j++){
    a += (r()-.5)*1.1;
    const d=.03+r()*.075;
    x += Math.cos(a)*d; y += Math.sin(a)*d*.9;
    pts.push({x,y});
  }
  lines.push(pts);
 }
 // few concentric arcs?
 return lines;
}
```
