    const len = 3 + Math.floor(r() * 5);
    for (let j = 0; j < len; j++) {
      a += (r() - 0.5) * 1.15;
      const d = 0.025 + r() * 0.085;
      x += Math.cos(a) * d;
      y += Math.sin(a) * d * 0.92;
