    g.setLineDash([]);
    g.fillStyle = 'rgba(255,190,150,.3)';
    g.font = '6px "Courier New",monospace';
    g.textAlign = 'center';
    g.fillText('SPEAKER', r.x + r.w / 2, r.y + r.h / 2 + 2);
