 });
 const t=currentTask();
 if(t){ nowTitle.textContent=t.label; nowHint.textContent=t.hint; needTool.innerHTML='Tool: <b>'+TOOL_NAMES[t.tool]+'</b>'; }
 else { nowTitle.textContent='Done!'; ... }
