```js
function handleDown(p){
 if(G.mode!=='playing'||G.jobDone||G.locked) return;
 const t=currentTask(); if(!t) return;
 // install drag
 if(t.type==='install'){
  const slot=traySlots().find(s=>s.part===t.part && !partInstalled(s.part) && inRect(p,slotHit(s),14));
  if(slot){ G.drag={kind:'install',part:t.part,x:p.x,y:p.y}; sfx('pick'); return; }
  toast('Grab the new '+PART_LABEL[t.part].toLowerCase()+' from the tray.');
  return;
 }
 // remove drag
 if(t.type==='remove'){
  const hit = t.part==='screen'? inSideScreen(p) : t.part==='protector'? inScreen(p) : inRect(p,PART_RECTS[t.part]||{x:0,y:0,w:0,h:0},8);
  if(!hit){ toast(...); return; }
  if(G.selected!==t.tool){ wrongTool(t); return; }
  if(t.part==='screen' && G.phone.openT<0.55){ toast('Lift the screen first.'); return; }
  G.drag={kind:'remove',part:t.part,x:p.x,y:p.y}; sfx('pick'); return;
 }
 // test
 if(t.type==='test'){
  if(dist(p.x,p.y,POWER.x-2,POWER.y+20)<50 || inPhone(p,12)){ startTest(); }
  else toast('Tap the power button on the right edge.');
  return;
 }
 // tool gating for remaining
 if(G.selected!==t.tool){
   if(taskTargetHit(p,t)) wrongTool(t);
   return;
 }
 switch(t.type){...}
}
```
