import { createRequire } from 'node:module'
import { readFileSync, mkdirSync } from 'node:fs'
const runtime = '/home/runner/.local/share/omgithub-playwright'
const require = createRequire(runtime + '/package.json')
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(runtime + '/linux.json', 'utf8'))
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(runtime + '/display', 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions })
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } })
page.on('pageerror', e => console.log('PAGEERROR', e.message))
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE', m.text()) })
await page.goto(process.argv[2] || 'http://localhost:3000', { waitUntil: 'load' })
await page.waitForTimeout(1500)
mkdirSync('/home/runner/work/PlayGround/PlayGround/screenshots', { recursive: true })
await page.screenshot({ path: process.argv[3] || '/home/runner/work/PlayGround/PlayGround/screenshots/title.jpg', type: 'jpeg', quality: 82 })
const info = await page.evaluate(() => {
  const b = document.getElementById('startBtn')
  const r = b.getBoundingClientRect()
  const el = document.elementFromPoint(r.x + r.width / 2, r.y + r.height / 2)
  const cs = getComputedStyle(b)
  return { rect: { x: r.x, y: r.y, w: r.width, h: r.height }, at: el && (el.id || el.className || el.tagName), opacity: cs.opacity, transform: getComputedStyle(document.getElementById('stage')).transform }
})
console.log(JSON.stringify(info, null, 2))
if (process.argv[4] === 'click') {
  await page.click('#startBtn', { timeout: 5000 }).catch(e => console.log('CLICK FAIL', e.message.split('\n')[0]))
  await page.waitForTimeout(1200)
  await page.screenshot({ path: process.argv[5] || '/home/runner/work/PlayGround/PlayGround/screenshots/day1.jpg', type: 'jpeg', quality: 82 })
  console.log('clicked')
}
await browser.close()

