import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
const runtime = '/home/runner/.local/share/omgithub-playwright'
const require = createRequire(runtime + '/package.json')
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(runtime + '/linux.json', 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(runtime + '/display', 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions })
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } })
const errors = []
page.on('pageerror', e => { errors.push(e.message); console.log('PAGEERROR', e.message) })
page.on('console', m => { if (m.type() === 'error') { errors.push(m.text()); console.log('CONSOLE', m.text()) } })
await page.goto('http://localhost:3000', { waitUntil: 'load' })
await page.waitForTimeout(1000)
await page.click('#startBtn')
await page.waitForTimeout(700)

const rect = await page.evaluate(() => {
  const r = document.getElementById('scene').getBoundingClientRect()
  return { left: r.left, top: r.top, w: r.width, h: r.height }
})
const pt = (x, y) => ({ x: rect.left + x / 1200 * rect.w, y: rect.top + y / 760 * rect.h })
async function moveTo(x, y, steps = 8) {
  const c = pt(x, y)
  await page.mouse.move(c.x, c.y, { steps })
}
async function down(x, y) {
  const c = pt(x, y)
  await page.mouse.move(c.x, c.y)
  await page.mouse.down()
}
async function up(x, y) {
  const c = pt(x, y)
  await page.mouse.move(c.x, c.y, { steps: 10 })
  await page.mouse.up()
}
async function drag(x1, y1, x2, y2) {
  await down(x1, y1)
  await page.waitForTimeout(100)
  await up(x2, y2)
}
async function swipe(x1, y1, x2, y2, times = 1) {
  for (let i = 0; i < times; i++) {
    await down(x1, y1)
    await moveTo(x2, y2, 30)
    await page.mouse.up()
    if (i === 0) await page.waitForTimeout(50)
    await down(x2, y2)
    await moveTo(x1, y1, 30)
    await page.mouse.up()
  }
}
const state = async () => page.evaluate(() => ({
  task: document.getElementById('nowTitle').textContent,
  progress: window.__ps.G.tasks[window.__ps.G.ti] ? (window.__ps.G.tasks[window.__ps.G.ti].progress || 0) : -1,
  mode: window.__ps.G.mode,
  patience: window.__ps.G.patience,
  done: window.__ps.G.tasks.filter(t => t.done).length,
  phone: {
    peeled: window.__ps.G.phone.protectorPeeled,
    protectorNew: window.__ps.G.phone.protectorNew,
    bubbles: window.__ps.G.phone.bubbles,
    clean: window.__ps.G.phone.clean
  }
}))

console.log('start:', await state())
await drag(600, 380, 290, 575)
await page.waitForTimeout(300)
console.log('after peel:', await state())
await swipe(510, 250, 690, 250, 2)
await swipe(515, 320, 685, 320, 2)
await page.waitForTimeout(200)
console.log('after clean:', await state())
await drag(808, 400, 600, 380)
await page.waitForTimeout(300)
console.log('after install:', await state())
await swipe(510, 250, 690, 250, 2)
await swipe(515, 340, 685, 340, 2)
await page.waitForTimeout(200)
console.log('after smooth:', await state())
await page.mouse.click(pt(722, 261).x, pt(722, 261).y)
await page.waitForTimeout(3200)
await page.screenshot({ path: 'screenshots/receipt.jpg', type: 'jpeg', quality: 82 })
console.log('after boot:', await state())
console.log('receipt visible:', await page.evaluate(() => !document.getElementById('receipt').classList.contains('hidden')))
console.log('errors:', errors)
