366: function nearestScrew(p, where) {
367:   const set = SCREW_SETS[where];
368:   let best = null;
369:   set.forEach((s, i) => {
370:     if (G.phone.screwProg[where][i] >= 1) return;
371:     const d = dist(p.x, p.y, s.x, s.y);
372:     if (d < 28 && (!best || d < best.d)) best = { i, s, d };
373:   });
374:   return best;
375: }
376: function targetHit(p, t) {
377:   switch (t.type) {
378:     case 'heat': return inPhone(p, 12);
379:     case 'pry': return inScreen(p, 14) || (G.phone.openT > 0.5 && inSideScreen(p));
380:     case 'unscrew': return Boolean(nearestScrew(p, t.where));
381:     case 'disconnect': {
382:       const c = CONNECTORS[t.name];
383:       return dist(p.x, p.y, c.x, c.y) < 30 && G.phone.connectors[t.name];
384:     }
385:     case 'remove':
386:       if (t.part === 'screen') return inSideScreen(p);
387:       if (t.part === 'protector') return inScreen(p, 10);
388:       return inRect(p, PART_RECTS[t.part], 10) && G.phone.parts[t.part] !== 'gone';
389:     case 'close': return inPhone(p, 12);
390:     case 'clean':
391:     case 'smooth': return inScreen(p, 14);
392:     case 'dry':
393:     case 'scrub': return inRect(p, INNER, 20);
394:     case 'test': return dist(p.x, p.y, POWER.x, POWER.y) < 52;
395:   }
396:   return false;
397: }
