437: function handleDown(p) {
438:   if (G.mode !== 'playing' || G.jobDone || G.locked) return;
439:   const t = currentTask();
440:   if (!t) return;
441: 
442:   if (t.type === 'install') {
443:     const slot = traySlots().find((s) => s.part === t.part && !partInstalled(s.part) && inRect(p, slotHit(s)));
444:     if (slot) {
445:       G.drag = { kind: 'install', part: t.part, x: p.x, y: p.y };
446:       sfx('pick');
447:     } else {
448:       toast('Grab the new ' + PART_LABEL[t.part].toLowerCase() + ' from the parts tray.');
449:     }
450:     return;
451:   }
452: 
453:   if (t.type === 'remove') {
454:     let hit = false;
455:     if (t.part === 'screen') hit = inSideScreen(p) && G.phone.openT > 0.45;
456:     else if (t.part === 'protector') hit = inScreen(p, 10);
457:     else hit = inRect(p, PART_RECTS[t.part], 10);
458:     if (!hit) {
459:       toast(t.part === 'screen' ? 'The loose screen is over on the left.' : 'Grab the old part on the phone.');
460:       return;
461:     }
462:     if (G.selected !== t.tool) {
463:       wrongTool(t);
464:       return;
465:     }
466:     G.drag = { kind: 'remove', part: t.part, x: p.x, y: p.y };
467:     sfx('pick');
468:     return;
469:   }
470: 
471:   if (t.type === 'test') {
472:     if (dist(p.x, p.y, POWER.x, POWER.y) < 52 || inPhone(p, 14)) startTest();
473:     else toast('Tap the power button on the right edge of the phone.');
474:     return;
475:   }
476: 
477:   if (G.selected !== t.tool) {
478:     if (targetHit(p, t)) wrongTool(t);
479:     return;
480:   }
481: 
482:   switch (t.type) {
483:     case 'heat':
484:       if (inPhone(p, 12)) startHold(p, 'action', { need: t.need, progress: t.progress, r: 30 });
485:       else toast('Hold the heat gun over the phone.');
486:       break;
487:     case 'pry':
488:       if (inScreen(p, 14) || inPhone(p, 10)) {
489:         G.drag = { kind: 'pry', startY: p.y, lift: 0 };
490:         G.phone.openTarget = 0;
491:       }
492:       break;
493:     case 'unscrew': {
494:       const hit = nearestScrew(p, t.where);
495:       if (hit) startHold(p, 'screw', { idx: hit.i, where: t.where, progress: G.phone.screwProg[t.where][hit.i], need: 0.85, r: 14 });
496:       else toast('Find the little screws at the bottom of the phone.');
497:       break;
498:     }
499:     case 'disconnect': {
500:       const c = CONNECTORS[t.name];
501:       if (dist(p.x, p.y, c.x, c.y) < 32) startHold({ x: c.x, y: c.y }, 'action', { need: 0.65, progress: t.progress, r: 24 });
502:       else toast('Look for the little gold connector on the board.');
503:       break;
504:     }
505:     case 'close':
506:       if (inPhone(p, 14)) startHold(p, 'action', { need: t.need, progress: t.progress, r: 32 });
507:       break;
508:     case 'clean':
509:     case 'smooth':
510:       if (inScreen(p, 18)) {
511:         G.cloth = { task: t, last: p };
512:       }
513:       break;
514:     case 'scrub':
515:       if (inRect(p, INNER, 20)) {
516:         G.cloth = { task: t, last: p };
517:       } else toast('Drag the cloth over the green gunk on the board.');
518:       break;
519:     case 'dry':
520:       if (inRect(p, INNER, 18)) startHold(p, 'action', { need: t.need, progress: t.progress, r: 30 });
521:       else toast('Hold the heat gun inside the open phone.');
522:       break;
523:   }
524: }
