551:       t.progress = clamp((t.progress || 0) + d / 640, 0, 1);
552:       if (t.type === 'clean') G.phone.clean = t.progress;
553:       else G.phone.bubbles = 1 - t.progress;
554:     }
555:     if (Math.random() < 0.015) sfx('heat');
