557:       G.cloth = null;
558:       if (t.type === 'clean') G.phone.clean = 1;
559:       if (t.type === 'smooth') G.phone.bubbles = 0;
560:       if (t.type === 'scrub') G.phone.corrosion = 0;
561:       burst(p.x, p.y, { n: 12, color: '#dff6ec', speed: 60 });
562:       completeTask();
563:     }
564:   }
