646: function updateHold(dt) {
647:   const h = G.hold;
648:   if (!h || !G.down) return;
649:   const t = currentTask();
650:   if (!t || G.locked) return;
651:   h.progress += dt / (h.need || 1);
652:   if (h.type === 'screw') {
653:     const pr = Math.min(1, h.progress);
654:     G.phone.screwProg[h.where][h.idx] = pr;
655:     if (pr >= 1) {
656:       G.hold = null;
657:       sfx('unscrew');
658:       burst(h.x, h.y, { n: 7, color: '#d8e4ec', speed: 55 });
659:       if (G.phone.screwProg[h.where].every((v) => v >= 1)) {
660:         G.phone.screwsRemoved[h.where] = true;
661:         completeTask();
662:       }
663:     }
664:     return;
665:   }
666:   t.progress = Math.min(1, h.progress);
667:   if (h.type === 'action' && t.type === 'heat') {
668:     G.phone.heat = t.progress;
669:     if (Math.random() < dt * 6) burst(h.x, h.y, { n: 1, color: 'rgba(255,200,140,.8)', speed: 30, life: 0.5, size: 1.6 });
670:   }
671:   if (h.type === 'action' && t.type === 'dry') {
672:     G.phone.dry = t.progress;
673:     if (Math.random() < dt * 8) burst(h.x, h.y, { n: 1, color: 'rgba(220,240,250,.8)', speed: 40, life: 0.7, size: 1.4 });
674:   }
675:   if (h.progress >= 1) {
676:     G.hold = null;
677:     switch (t.type) {
678:       case 'heat':
679:         sfx('pop');
680:         burst(h.x, h.y, { n: 10, color: '#ffb066' });
681:         completeTask();
682:         break;
683:       case 'dry':
684:         sfx('pop');
685:         G.phone.corrosion = Math.max(0.45, G.phone.corrosion);
686:         burst(h.x, h.y, { n: 10, color: '#bfe4ee' });
687:         completeTask();
688:         break;
689:       case 'disconnect':
690:         G.phone.connectors[t.name] = false;
691:         sfx('pop');
692:         burst(h.x, h.y, { n: 8, color: '#ffd27a' });
693:         completeTask();
694:         break;
695:       case 'close':
696:         beginClose();
697:         break;
698:     }
699:   }
700: }
