711: function update(dt) {
712:   G.time += dt;
713:   const p = G.phone;
714: 
715:   if (G.mode === 'playing' && !G.jobDone) {
716:     if (!G.testing) G.elapsed += dt;
717:     G.patience = clamp(1 - G.elapsed / G.order.limit - G.penalty, 0, 1);
718:     if (!G.locked) updateHold(dt);
719:     if (G.closing > 0) {
720:       G.closing -= dt;
721:       if (G.closing <= 0) {
722:         G.locked = false;
723:         completeTask();
724:       }
725:     }
726:     if (G.testing && p.powerOn) {
727:       if (p.bootT > 2.5) {
728:         G.testing = false;
729:         completeTask();
730:       }
731:     }
732:     updateHud();
733:   }
734: 
735:   if (G.jobDone && G.mode === 'playing') {
736:     G.finishTimer -= dt;
737:     if (G.finishTimer <= 0) showReceipt();
738:   }
739: 
740:   if (p) {
741:     p.openT += (p.openTarget - p.openT) * Math.min(1, dt * 7);
742:     p.seat += (p.seatTarget - p.seat) * Math.min(1, dt * 9);
743:     if (p.powerOn) p.bootT += dt;
744:   }
745: 
746:   // particles
747:   G.particles = G.particles.filter((q) => {
748:     q.life -= dt;
749:     q.x += q.vx * dt;
750:     q.y += q.vy * dt;
751:     q.vy += (q.gravity || 0) * dt;
752:     q.vx *= 0.985;
753:     q.vy *= 0.985;
754:     q.rot += q.vr * dt;
755:     return q.life > 0;
756:   });
757: 
758:   if (G.toastTimer > 0) {
759:     G.toastTimer -= dt;
760:     if (G.toastTimer <= 0) toastEl.classList.remove('show');
761:   }
762:   if (G.bannerTimer > 0) {
763:     G.bannerTimer -= dt;
764:     if (G.bannerTimer <= 0) bannerEl.classList.remove('show');
765:   }
766: }
