import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
const runtime = '/home/runner/.local/share/omgithub-playwright'
const require = createRequire(runtime + '/package.json')
const { chromium } = require('playwright')
const browser = await chromium.launch({ headless: true })
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } })
const errors = []
page.on('pageerror', e => { errors.push(e.message); console.log('PAGEERROR', e.message) })
page.on('console', m => { if (m.type() === 'error') { errors.push(m.text()); console.log('CONSOLE', m.text()) } })
await page.goto('http://localhost:3000', { waitUntil: 'load' })
await page.waitForTimeout(700)
await page.click('#startBtn')
await page.waitForTimeout(600)

const rect = await page.evaluate(() => {
  const r = document.getElementById('scene').getBoundingClientRect()
  return { left: r.left, top: r.top, w: r.width, h: r.height }
})
const pt = (x, y) => ({ x: rect.left + x / 1200 * rect.w, y: rect.top + y / 760 * rect.h })
async function pos(x, y) { const c = pt(x, y); await page.mouse.move(c.x, c.y); return c }
async function hold(x, y, ms) {
  await pos(x, y); await page.mouse.down(); await page.waitForTimeout(ms); await page.mouse.up(); await page.waitForTimeout(140)
}
async function drag(x1, y1, x2, y2, steps = 28) {
  await pos(x1, y1); await page.mouse.down(); await page.waitForTimeout(70)
  const b = pt(x2, y2); await page.mouse.move(b.x, b.y, { steps }); await page.mouse.up(); await page.waitForTimeout(220)
}
async function swipe(x1, y1, x2, y2) {
  await pos(x1, y1); await page.mouse.down()
  const b = pt(x2, y2); await page.mouse.move(b.x, b.y, { steps: 24 }); await page.mouse.up()
  await page.waitForTimeout(60)
}
const state = () => page.evaluate(() => {
  const G = window.__ps.G
  const t = G.tasks[G.ti]
  return {
    day: G.day, mode: G.mode, ti: G.ti, done: G.tasks.filter(x => x.done).length,
    total: G.tasks.length, task: t ? t.label : null, type: t ? t.type : null,
    where: t ? t.where : null, part: t ? t.part : null, progress: t ? (t.progress || 0) : -1,
    mistakes: G.mistakes, money: G.money
  }
})
const SCREWS = { bottom: [[508, 600], [692, 600]], port: [[536, 552], [664, 552]], speaker: [[552, 514], [648, 514]] }
const CONN = { display: [657, 312], battery: [678, 352], camera: [626, 214] }
const PART_C = { battery: [612, 410], camera: [538, 210], speaker: [600, 543], port: [600, 583] }

async function workTask() {
  const s = await state()
  if (s.mode !== 'playing' || !s.type) return s
  switch (s.type) {
    case 'heat': await hold(600, 380, 2500); break
    case 'unscrew': {
      for (const [x, y] of SCREWS[s.where]) { await hold(x, y, 1000); }
      break
    }
    case 'pry': await drag(600, 420, 600, 290, 32); await page.waitForTimeout(400); break
    case 'disconnect': { const [x, y] = CONN[s.part || 'battery']; await hold(x, y, 850); break }
    case 'remove': {
      if (s.part === 'screen') await drag(398, 326, 290, 576)
      else if (s.part === 'protector') await drag(600, 380, 290, 576)
      else { const [x, y] = PART_C[s.part]; await drag(x, y, 290, 576) }
      break
    }
    case 'install': {
      let from
      if (s.part === 'battery') from = [808, 520]
      else if (s.part === 'screen' || s.part === 'protector') from = [808, 338]
      else from = [808, 400]
      if (s.part === 'protector') from = [808, 400]
      const to = (s.part === 'screen' || s.part === 'protector') ? [600, 380] : PART_C[s.part]
      await drag(from[0], from[1], to[0], to[1])
      break
    }
    case 'close': await hold(600, 400, 1200); await page.waitForTimeout(700); break
    case 'clean':
    case 'smooth': {
      const y = s.type === 'clean' ? 300 : 320
      await swipe(512, y, 688, y); await swipe(688, y, 512, y)
      await swipe(512, y + 50, 688, y + 50); await swipe(688, y + 50, 512, y + 50)
      await page.waitForTimeout(250)
      break
    }
    case 'scrub': {
      for (let i = 0; i < 3; i++) { await swipe(510, 300, 690, 300); await swipe(690, 300, 510, 300) }
      await page.waitForTimeout(250)
      break
    }
    case 'dry': await hold(600, 380, 2850); break
    case 'test': {
      await pos(722, 261); await page.mouse.click(pt(722, 261).x, pt(722, 261).y)
      for (let i = 0; i < 60; i++) { await page.waitForTimeout(100); const q = await state(); if (q.mode !== 'playing') break }
      break
    }
  }
  return state()
}

const NAMES = ['protector', 'screen', 'battery', 'port', 'water', 'camera', 'speaker', 'both']
const results = []
for (let day = 0; day < 8; day++) {
  await page.evaluate((d) => { window.__ps.G.day = d; window.__ps.startDay() }, day)
  await page.waitForTimeout(900)
  let steps = 0
  let last = null
  while (steps < 40) {
    const s = await state()
    last = s
    if (s.mode !== 'playing' || !s.type) break
    await workTask()
    steps++
  }
  const s = await state()
  const receiptVisible = await page.evaluate(() => !document.getElementById('receipt').classList.contains('hidden'))
  const receipt = await page.evaluate(() => ({
    model: document.getElementById('rModel').textContent,
    repair: document.getElementById('rRepair').textContent,
    total: document.getElementById('rTotal').textContent,
    stars: document.getElementById('rStars').textContent,
    next: document.getElementById('nextBtn').textContent
  }))
  results.push({ day: day + 1, name: NAMES[day], steps, mode: s.mode, done: s.done, total: s.total, mistakes: s.mistakes, receiptVisible, receipt, task: s.task })
  console.log(JSON.stringify(results[results.length - 1]))
  if (!receiptVisible) { console.log('  !!! receipt not shown; last state', JSON.stringify(last)); break }
  const isLast = day === 7
  await page.click('#nextBtn')
  await page.waitForTimeout(900)
  console.log('  after next ->', await page.evaluate(() => ({ mode: window.__ps.G.mode, day: window.__ps.G.day, summary: !document.getElementById('summary').classList.contains('hidden') })))
  if (isLast) break
}
const summary = await page.evaluate(() => ({
  visible: !document.getElementById('summary').classList.contains('hidden'),
  rank: document.getElementById('sumRank').textContent,
  jobs: document.getElementById('sumJobs').textContent,
  money: document.getElementById('sumMoney').textContent,
  rating: document.getElementById('sumRating').textContent,
  best: document.getElementById('sumBest').textContent,
  stars: document.getElementById('sumStars').textContent,
  line: document.getElementById('sumLine').textContent
}))
console.log('SUMMARY', JSON.stringify(summary))
console.log('ERRORS', JSON.stringify(errors))
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/summary.jpg', type: 'jpeg', quality: 82 })
await browser.close()

