const CONN = { display: [657, 312], battery: [678, 352], camera: [626, 214] }
async function advanceTo(predicate, limit = 30) {
  for (let i = 0; i < limit; i++) {
    const s = await state()
    if (s.mode !== 'playing' || !s.type) return s
    if (predicate(s)) return s
