import { createRequire } from 'node:module'
const runtime = '/home/runner/.local/share/omgithub-playwright'
const require = createRequire(runtime + '/package.json')
const { chromium } = require('playwright')
const browser = await chromium.launch({ headless: true })
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } })
const errors = []
page.on('pageerror', e => { errors.push(e.message); console.log('PAGEERROR', e.message) })
page.on('console', m => { if (m.type() === 'error') { errors.push(m.text()); console.log('CONSOLE', m.text()) } })
await page.goto('http://localhost:3000', { waitUntil: 'load' })
await page.evaluate(() => localStorage.removeItem('pixelward.best'))
await page.waitForTimeout(600)
await page.click('#startBtn')
await page.waitForTimeout(700)
const rect = await page.evaluate(() => { const r = document.getElementById('scene').getBoundingClientRect(); return { left: r.left, top: r.top, w: r.width, h: r.height } })
const pt = (x, y) => ({ x: rect.left + x / 1200 * rect.w, y: rect.top + y / 760 * rect.h })
async function pos(x, y) { const c = pt(x, y); await page.mouse.move(c.x, c.y); return c }
async function hold(x, y, ms) { await pos(x, y); await page.mouse.down(); await page.waitForTimeout(ms); await page.mouse.up(); await page.waitForTimeout(120) }
async function drag(x1, y1, x2, y2, steps = 26) { await pos(x1, y1); await page.mouse.down(); await page.waitForTimeout(60); const b = pt(x2, y2); await page.mouse.move(b.x, b.y, { steps }); await page.mouse.up(); await page.waitForTimeout(200) }
async function swipe(x1, y1, x2, y2) { await pos(x1, y1); await page.mouse.down(); const b = pt(x2, y2); await page.mouse.move(b.x, b.y, { steps: 20 }); await page.mouse.up(); await page.waitForTimeout(40) }
const state = () => page.evaluate(() => {
  const G = window.__ps.G; const t = G.tasks[G.ti]
  const installs = []
  for (const x of G.tasks) if (x.type === 'install' && !installs.includes(x.part)) installs.push(x.part)
  installs.sort((a, b) => (a === 'screen' || a === 'protector') ? -1 : (b === 'screen' || b === 'protector') ? 1 : 0)
  return { day: G.day, mode: G.mode, ti: G.ti, total: G.tasks.length, installs, type: t ? t.type : null, where: t ? t.where : null, part: t ? t.part : null, name: t ? t.name : null, task: t ? t.label : null, money: G.money, patience: G.patience }
})
const SCREWS = { bottom: [[508, 600], [692, 600]], port: [[536, 552], [664, 552]], speaker: [[552, 514], [648, 514]] }
const CONN = { display: [657, 312], battery: [678, 352], camera: [626, 214] }
const PART_C = { battery: [612, 410], camera: [538, 210], speaker: [600, 543], port: [600, 583] }
async function work(s) {
  switch (s.type) {
    case 'heat': await hold(600, 380, 2500); break
    case 'unscrew': for (const [x, y] of SCREWS[s.where]) await hold(x, y, 1000); break
    case 'pry': await drag(600, 420, 600, 290, 30); await page.waitForTimeout(450); break
    case 'disconnect': { const [x, y] = CONN[s.name]; await hold(x, y, 850); break }
    case 'remove':
      if (s.part === 'screen') await drag(398, 326, 290, 576)
      else if (s.part === 'protector') await drag(600, 380, 290, 576)
      else { const [x, y] = PART_C[s.part]; await drag(x, y, 290, 576) }
      break
    case 'install': {
      const slots = s.installs.length === 1 ? { [s.installs[0]]: [808, 400] } : { [s.installs[0]]: [808, 338], [s.installs[1]]: [808, 520] }
      const from = slots[s.part]
      const to = (s.part === 'screen' || s.part === 'protector') ? [600, 380] : PART_C[s.part]
      await drag(from[0], from[1], to[0], to[1]); break
    }
    case 'close': await hold(600, 400, 1200); await page.waitForTimeout(700); break
    case 'clean': case 'smooth': {
      const y = s.type === 'clean' ? 300 : 320
      await swipe(512, y, 688, y); await swipe(688, y, 512, y)
      await swipe(512, y + 50, 688, y + 50); await swipe(688, y + 50, 512, y + 50)
      break
    }
    case 'scrub': for (let i = 0; i < 3; i++) { await swipe(510, 300, 690, 300); await swipe(690, 300, 510, 300) } break
    case 'dry': await hold(600, 380, 2850); break
    case 'test': {
      await page.mouse.click(pt(722, 261).x, pt(722, 261).y)
      for (let i = 0; i < 70; i++) { await page.waitForTimeout(100); const q = await state(); if (q.mode !== 'playing') break }
      break
    }
  }
}
const days = []
for (let d = 0; d < 8; d++) {
  let s = await state()
  console.log('DAY', s.day + 1, 'start', JSON.stringify({ task: s.task, total: s.total, money: s.money }))
  let steps = 0
  while (s.mode === 'playing' && s.type && steps < 40) { await work(s); s = await state(); steps++ }
  const receipt = await page.evaluate(() => ({
    visible: !document.getElementById('receipt').classList.contains('hidden'),
    model: document.getElementById('rModel').textContent,
    repair: document.getElementById('rRepair').textContent,
    time: document.getElementById('rTime').textContent,
    total: document.getElementById('rTotal').textContent,
    stars: document.getElementById('rStars').textContent,
    next: document.getElementById('nextBtn').textContent
  }))
  days.push({ day: d + 1, steps, mode: s.mode, money: s.money, receipt })
  console.log('  ->', JSON.stringify(days[days.length - 1]))
  if (!receipt.visible) { console.log('  ABORT: no receipt'); break }
  await page.screenshot({ path: `/home/runner/work/PlayGround/PlayGround/screenshots/run-day${d + 1}.jpg`, type: 'jpeg', quality: 82 })
  await page.click('#nextBtn')
  await page.waitForTimeout(950)
}
const summary = await page.evaluate(() => ({
  visible: !document.getElementById('summary').classList.contains('hidden'),
  mode: window.__ps.G.mode,
  rank: document.getElementById('sumRank').textContent,
  jobs: document.getElementById('sumJobs').textContent,
  money: document.getElementById('sumMoney').textContent,
  rating: document.getElementById('sumRating').textContent,
  bestDay: document.getElementById('sumBest').textContent,
  stars: document.getElementById('sumStars').textContent,
  line: document.getElementById('sumLine').textContent,
  bestRun: document.getElementById('bestRun').textContent
}))
console.log('SUMMARY', JSON.stringify(summary))
console.log('ERRORS', JSON.stringify(errors))
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/final-summary.jpg', type: 'jpeg', quality: 84 })
// replay sanity
if (summary.visible) {
  await page.click('#replayBtn'); await page.waitForTimeout(1000)
  console.log('REPLAY', JSON.stringify(await page.evaluate(() => ({ mode: window.__ps.G.mode, day: window.__ps.G.day, money: window.__ps.G.money, titleHidden: document.getElementById('titleScreen').classList.contains('hidden'), summaryHidden: document.getElementById('summary').classList.contains('hidden') }))))
}
console.log('FINAL ERRORS', JSON.stringify(errors))
await browser.close()

